"""Migrated Meridian CRM discount policy rules ORD-001 and ORD-002."""

from decimal import Decimal
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric_value(value: Any) -> Decimal:
    """Apply legacy numeric coercion; an empty string has numeric value zero."""
    if value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _lookup_role(user_id: str, users: list[dict]) -> Any:
    """Return ROLE_ID from the first matching live row, or an empty string."""
    for user in users:
        if user.get("DEL_FLG", "") != "Y" and user.get("USR_ID") == user_id:
            return user.get("ROLE_ID", "")
    return ""


def set_discount(
    order: dict,
    pct: Any,
    user_id: str,
    users: list[dict],
) -> dict:
    """Validate and set an order discount without mutating supplied objects."""
    numeric_pct = _numeric_value(pct)

    # ORD-001: evaluated first in legacy rule-file order.
    if not (Decimal(0) <= numeric_pct <= Decimal(100)):
        raise BusinessRuleViolation("E5001", "Discount out of range")

    # ORD-002: exactly 20 requires no role.
    if numeric_pct > Decimal(20):
        role = _lookup_role(user_id, users)
        if role not in ("MGR", "ADMIN"):
            raise BusinessRuleViolation(
                "E5002",
                "Discount over 20 percent requires manager role",
            )

    migrated_order = order.copy()
    migrated_order["DISC_PCT"] = pct
    return migrated_order
